import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/TowardATheoryOfTokenizationInLLMs.html","title":"TowardATheoryOfTokenizationInLLMs","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":0.49,"words":148},"filePathRelative":"TowardATheoryOfTokenizationInLLMs.md"}`),a={name:`TowardATheoryOfTokenizationInLLMs.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="towardatheoryoftokenizationinllms" tabindex="-1"><a class="header-anchor" href="#towardatheoryoftokenizationinllms"><span>TowardATheoryOfTokenizationInLLMs</span></a></h1><p><a href="./論文.html">論文</a>, <a href="./原論文から解き明かす生成AI.html">原論文から解き明かす生成AI</a></p><p><a href="https://arxiv.org/abs/2404.08335" target="_blank" rel="noopener noreferrer">arxiv:2404.08335 Toward a Theory of Tokenization in LLMs</a></p><h2 id="基本的な設定" tabindex="-1"><a class="header-anchor" href="#基本的な設定"><span>基本的な設定</span></a></h2><p><img src="/RandomThoughts/assets/0000-CfH3R3kC.png" alt="imgs/TkInLLMs2/0000.png"></p><h2 id="k次のスイッチングマルコフ" tabindex="-1"><a class="header-anchor" href="#k次のスイッチングマルコフ"><span>k次のスイッチングマルコフ</span></a></h2><p><img src="/RandomThoughts/assets/0001-Ca_Jw7fi.png" alt="imgs/TkInLLMs2/0001.png"></p><h2 id="ユニグラムのコスト" tabindex="-1"><a class="header-anchor" href="#ユニグラムのコスト"><span>ユニグラムのコスト</span></a></h2><p>まずはマルコフ性を無視したユニグラムの言語モデルでは、どの程度の無駄があるかを、対数尤度のlower boundから考える。</p><p>真の分布をPとして、ユニグラムによる言語モデルの値をQとする。Pでの期待値である事に留意すると以下。（スイッチングのケースは<a href="./マルコフ連鎖.html">マルコフ連鎖</a>も参照、Dは<a href="./KLダイバージェンス.html">KLダイバージェンス</a>）</p><p><img src="/RandomThoughts/assets/0000-BV7CVPT5.png" alt="imgs/TkInLLMs/0000.png"><img src="/RandomThoughts/assets/0001-CWF9wv8x.png" alt="imgs/TkInLLMs/0001.png"><img src="/RandomThoughts/assets/0002-Cv41icnT.png" alt="imgs/TkInLLMs/0002.png"></p><p>不等号は<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>Q</mi><mi mathvariant="normal">#</mi></msub><mo stretchy="false">(</mo><mi>m</mi><mo stretchy="false">)</mo></mrow><annotation encoding="application/x-tex">Q_\\#(m)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0361em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal">Q</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">#</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal">m</span><span class="mclose">)</span></span></span></span>の分。最後はmを忘れている気がする。</p><p>ユニグラムのコストはスイッチングのケースでデルタを極端な値に持っていけばいくらでも大きく出来るので、 ユニグラムのコストは大きくなりうる。</p><h2 id="トークナイゼーション入りモデル" tabindex="-1"><a class="header-anchor" href="#トークナイゼーション入りモデル"><span>トークナイゼーション入りモデル</span></a></h2><p>ユニグラムでは十分な最適化が行えないケースがありうるという事が示せたので、次はトークナイズを入れるとどうなるかを見ていく。</p><p><img src="/RandomThoughts/assets/0003-Q-DZMAPk.png" alt="imgs/TkInLLMs/0003.png"><img src="/RandomThoughts/assets/0004-6R6CP79S.png" alt="imgs/TkInLLMs/0004.png"><img src="/RandomThoughts/assets/0005-H21_2P12.png" alt="imgs/TkInLLMs/0005.png"></p><p>遷移核からエントロピーレートになる所（終わりから三行目から二行目になるところ）は<a href="./マルコフ連鎖.html">マルコフ連鎖</a>を参照のこと。</p><p>この最後の式は、rを大きくする（語彙サイズのdを大きくする）と、これはユニグラム制約無しの最適な値に近づいていく事を表す。</p>`,18)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};